import { NextRequest } from "next/server";
import { db, withTenantContext } from "@/lib/db";
import { supportsInteractiveTx } from "@/lib/db-adapter";
import { audit } from "@/lib/api-helpers";
import { startRun } from "@/lib/services/workflow-engine";
import { recordHookCall, verifyHookSignature } from "@/lib/services/autopilot";

export const dynamic = "force-dynamic";

/**
 * Citizen Lane — inbound production hooks.
 *
 * Two credential models are accepted:
 *
 *  1. AUTOPILOT (preferred) — a tokenised endpoint generated by the Autopilot
 *     engine. The URL is `/api/hooks/<token>` where <token> is an unguessable
 *     192-bit value, and every call MUST be signed:
 *         X-Signature: sha256=<hmac-sha256(rawBody, endpoint.secret)>
 *     A leaked URL alone cannot trigger a run; the secret is returned once at
 *     creation and can be rotated from the admin panel.
 *
 *  2. LEGACY — the workflow id itself is used as the URL (`/api/hooks/<workflowId>`).
 *     Still supported, but requests MUST always carry a matching `X-Signature`
 *     header: when INTEGRATION_WEBHOOK_SECRET is not configured the legacy path
 *     fails closed (401) instead of accepting the URL as a capability token.
 *
 * Every receipt — accepted, rejected, failed — is recorded in the OutboxEvent
 * ledger and audited; webhook failures are never silent. Runs flow through the
 * same engine, notifications and event hub as any other trigger.
 */

const json = (data: unknown, status = 200) => Response.json(data, { status });

/** Provider-supplied IDs make retries durable across processes and restarts. */
function inboundEventId(req: NextRequest): string | undefined {
  const value = req.headers.get("x-event-id") ?? req.headers.get("idempotency-key");
  const trimmed = value?.trim();
  return trimmed && trimmed.length <= 256 ? trimmed : undefined;
}

async function ledger(topic: string, status: "PROCESSED" | "DEAD_LETTER", facts: Record<string, unknown>) {
  try {
    await db.outboxEvent.create({ data: { topic, status, payload: JSON.stringify(facts) } });
  } catch (e) {
    console.error("[hooks] ledger write failed", e);
  }
}

/**
 * Legacy verification against the global INTEGRATION_WEBHOOK_SECRET. Fails
 * CLOSED: when the secret is not configured, unsigned legacy hooks are refused
 * outright — a leaked workflow id must never be enough to trigger a run.
 */
async function verifyGlobalSignature(req: NextRequest, rawBody: string): Promise<{ ok: boolean; reason?: string }> {
  const secret = process.env.INTEGRATION_WEBHOOK_SECRET;
  if (!secret) return { ok: false, reason: "INTEGRATION_WEBHOOK_SECRET is not configured" };
  const provided = req.headers.get("x-signature")?.trim();
  if (!provided) return { ok: false, reason: "missing X-Signature header" };
  if (!verifyHookSignature(secret, rawBody, provided)) return { ok: false, reason: "invalid signature" };
  return { ok: true };
}

/**
 * Run a hook DB unit inside the resolved tenant context (HOOKS slice T3/T4).
 * The org is known only AFTER endpoint/workflow resolution (T1 global), so
 * every unit below takes the resolved orgId. pg-only; Neon-HTTP and org-less
 * paths use the global client exactly as before. Audit units additionally
 * swallow scope failures (audit is best-effort by design); reads needed for
 * the response throw through, preserving current semantics.
 */
async function scoped<T>(orgId: string | null | undefined, fn: () => Promise<T>): Promise<T> {
  if (orgId && supportsInteractiveTx()) {
    return withTenantContext(orgId, () => fn());
  }
  return fn();
}

/** Shared JSON body parse → payload or an error response. */
async function parseBody(rawBody: string): Promise<{ ok: true; payload: Record<string, unknown> } | { ok: false }> {
  if (!rawBody) return { ok: true, payload: {} };
  try {
    const parsed = JSON.parse(rawBody) as unknown;
    return { ok: true, payload: parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : {} };
  } catch {
    return { ok: false };
  }
}

export async function GET(req: NextRequest, { params }: { params: Promise<{ hookId: string }> }) {
  const { hookId } = await params;

  // Autopilot token endpoint — minimal, non-disclosing health probe only.
  const endpoint = await db.hookEndpoint.findUnique({
    where: { token: hookId },
    include: { workflow: { select: { id: true, status: true, disabled: true } } },
  });
  if (endpoint) {
    const active = endpoint.active && endpoint.workflow?.status === "PUBLISHED" && !endpoint.workflow?.disabled;
    return json({ hook: "endpoint", active, signatureRequired: true });
  }

  // Legacy workflow-id probe — no workflow name/description is ever returned.
  const wf = await db.workflow.findUnique({
    where: { id: hookId },
    select: { id: true, status: true, disabled: true, currentVersion: true },
  });
  if (!wf) return json({ error: "Unknown hook — no workflow with this id" }, 404);
  const version = wf.currentVersion
    ? await db.workflowVersion.findUnique({ where: { workflowId_version: { workflowId: wf.id, version: wf.currentVersion } } })
    : null;
  const triggerKey = version ? (JSON.parse(version.nodes) as Array<{ pieceKey: string }>).find((n) => n.pieceKey.startsWith("trigger."))?.pieceKey : undefined;
  return json({
    hook: wf.id,
    active: wf.status === "PUBLISHED" && !wf.disabled,
    expectedTrigger: triggerKey,
    // Legacy hooks always require a signature now — they fail closed when the
    // secret is unset, so the value is no longer conditional.
    signatureRequired: true,
  });
}

export async function POST(req: NextRequest, { params }: { params: Promise<{ hookId: string }> }) {
  const { hookId } = await params;
  const rawBody = await req.text();

  const parsed = await parseBody(rawBody);
  if (!parsed.ok) {
    await ledger("hook.received", "DEAD_LETTER", { hookId, error: "invalid JSON body" });
    return json({ error: "Body must be valid JSON" }, 400);
  }
  const payload = parsed.payload;
  const eventId = inboundEventId(req);

  // ── Model 1: Autopilot tokenised endpoint (signature REQUIRED) ──
  const endpoint = await db.hookEndpoint.findUnique({
    where: { token: hookId },
    include: { workflow: { select: { id: true, status: true, disabled: true } } },
  });
  if (endpoint) {
    const wf = endpoint.workflow;
    if (!wf) {
      await ledger("hook.received", "DEAD_LETTER", { hookId, error: "endpoint has no workflow" });
      return json({ error: "Unknown hook" }, 404);
    }
    if (!endpoint.active || wf.disabled || wf.status !== "PUBLISHED") {
      await ledger("hook.received", "DEAD_LETTER", { hookId, endpointId: endpoint.id, error: "endpoint not active" });
      return json({ error: "This hook is not active (endpoint disabled or workflow unpublished)" }, 409);
    }
    const provided = req.headers.get("x-signature")?.trim() ?? "";
    if (!verifyHookSignature(endpoint.secret, rawBody, provided)) {
      await ledger("hook.received", "DEAD_LETTER", { hookId, endpointId: endpoint.id, error: "invalid signature" });
      await scoped(endpoint.orgId, () =>
        audit({ orgId: endpoint.orgId, action: "hook.rejected", target: endpoint.id, reason: "invalid signature" }),
      ).catch(() => undefined);
      return json({ error: "Signature verification failed" }, 401);
    }
    try {
      const run = await startRun({
        workflowId: wf.id,
        trigger: "hook.inbound",
        context: { ...payload, __hookId: hookId, __endpointId: endpoint.id },
        actorLabel: "Inbound hook (autopilot)",
        ...(eventId ? { dedupeKey: `inbound:${eventId}` } : {}),
      });
      await recordHookCall(endpoint.id, endpoint.orgId);
      await ledger("hook.received", "PROCESSED", { hookId, endpointId: endpoint.id, runId: run.id, contextKeys: Object.keys(payload) });
      await scoped(endpoint.orgId, () =>
        audit({ orgId: endpoint.orgId, action: "hook.received", target: endpoint.id, after: { runId: run.id } }),
      ).catch(() => undefined);
      const fresh = await scoped(endpoint.orgId, () =>
        db.workflowRun.findUnique({ where: { id: run.id }, select: { id: true, status: true, createdAt: true } }),
      );
      return json({ ok: true, run: fresh });
    } catch (err) {
      const message = err instanceof Error ? err.message : "hook run failed";
      await ledger("hook.received", "DEAD_LETTER", { hookId, endpointId: endpoint.id, error: message });
      return json({ error: message }, 500);
    }
  }

  // ── Model 2: legacy workflow-id endpoint ──
  const wf = await db.workflow.findUnique({ where: { id: hookId }, select: { id: true, name: true, orgId: true, status: true, disabled: true } });
  if (!wf) {
    await ledger("hook.received", "DEAD_LETTER", { hookId, error: "unknown workflow" });
    return json({ error: "Unknown hook — no workflow with this id" }, 404);
  }
  if (wf.disabled || wf.status !== "PUBLISHED") {
    await ledger("hook.received", "DEAD_LETTER", { hookId, workflowName: wf.name, error: "workflow not active" });
    return json({ error: "This hook is not active (workflow unpublished or disabled)" }, 409);
  }

  const sig = await verifyGlobalSignature(req, rawBody);
  if (!sig.ok) {
    await ledger("hook.received", "DEAD_LETTER", { hookId, workflowName: wf.name, error: sig.reason });
    await scoped(wf.orgId, () =>
      audit({ orgId: wf.orgId, action: "hook.rejected", target: wf.id, reason: sig.reason }),
    ).catch(() => undefined);
    return json({ error: `Signature verification failed: ${sig.reason}` }, 401);
  }

  try {
    const run = await startRun({
      workflowId: wf.id,
      trigger: "hook.inbound",
      context: { ...payload, __hookId: hookId },
      actorLabel: "Inbound hook",
      ...(eventId ? { dedupeKey: `inbound:${eventId}` } : {}),
    });
    await ledger("hook.received", "PROCESSED", { hookId, workflowName: wf.name, runId: run.id, contextKeys: Object.keys(payload) });
    await scoped(wf.orgId, () =>
      audit({ orgId: wf.orgId, action: "hook.received", target: wf.id, after: { runId: run.id } }),
    ).catch(() => undefined);
    const fresh = await scoped(wf.orgId, () =>
      db.workflowRun.findUnique({ where: { id: run.id }, select: { id: true, status: true, createdAt: true } }),
    );
    return json({ ok: true, run: fresh });
  } catch (err) {
    const message = err instanceof Error ? err.message : "hook run failed";
    await ledger("hook.received", "DEAD_LETTER", { hookId, workflowName: wf.name, error: message });
    return json({ error: message }, 500);
  }
}
